var AC=window.AudioContext||window.webkitAudioContext,ctx=null;
function actx(){if(!ctx){try{ctx=new AC()}catch(e){}}if(ctx&&ctx.state==='suspended')ctx.resume().catch(function(){});return ctx}
function noiseBuffer(c,sec){var b=c.createBuffer(1,Math.floor(c.sampleRate*sec),c.sampleRate),d=b.getChannelData(0);for(var i=0;i<d.length;i++)d[i]=Math.random()*2-1;return b}
function burst(c,dest,t,dur,freq,q,vol){var s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=noiseBuffer(c,dur+.02);f.type='bandpass';f.frequency.value=freq;f.Q.value=q;g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);s.connect(f);f.connect(g);g.connect(dest);s.start(t)}
function thump(){var c=actx();if(!c)return;var t=c.currentTime,o=c.createOscillator(),g=c.createGain();o.frequency.setValueAtTime(130,t);o.frequency.exponentialRampToValueAtTime(48,t+.14);g.gain.setValueAtTime(.7,t);g.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+.28);burst(c,c.destination,t,.05,900,.8,.35)}

