/* ================= 9. FAVORITES ================= */
var favs=store('gf-favs')||[];
var picksBtn=el('button','picks-btn','<span aria-hidden="true">♥</span> <b>0</b>');picksBtn.type='button';picksBtn.setAttribute('aria-label','My picks');
(function(){var nav=$('header nav');if(nav)nav.insertBefore(picksBtn,$('#theme-toggle',nav))})();
function isFav(src){return favs.indexOf(src)>-1}
function sync(){
  $$('[data-fav]').forEach(function(h){var on=isFav(h.getAttribute('data-fav'));h.classList.toggle('on',on);h.setAttribute('aria-pressed',on)});
  $('b',picksBtn).textContent=favs.length;picksBtn.classList.toggle('has',favs.length>0);
  if(GF.onFavs)GF.onFavs();
}
function toggleFav(src){var k=favs.indexOf(src);if(k>-1)favs.splice(k,1);else favs.push(src);store('gf-favs',favs);sync();renderTray()}
GF.sync=sync;GF.isFav=isFav;GF.favs=function(){return favs.slice()};
document.addEventListener('click',function(e){
  var h=e.target.closest('[data-fav]');if(h){e.preventDefault();e.stopPropagation();toggleFav(h.getAttribute('data-fav'))}
},true);
function picksText(){return favs.map(function(s){var p=item(s);return '- '+(p.title&&p.title!=='Photo'?p.title+' ':'')+'('+s+')'}).join('\n')}
function renderTray(){
  tray.innerHTML='<div class="pk-h"><b>My picks</b><button class="pk-x" aria-label="Close">×</button></div>'
   +(favs.length?'<ul class="pk-l">'+favs.map(function(s){var p=item(s);return '<li><img src="'+esc(s)+'" alt=""><span>'+esc(p.title||'Photo')+'</span><button data-fav="'+esc(s)+'" class="pk-r" aria-label="Remove">×</button></li>'}).join('')+'</ul>'
     :'<p class="pk-e">Tap the ♥ on any photo to save it here. Then send the list to me in one click.</p>')
   +'<div class="pk-b"><button class="gfb fill" data-act="send"'+(favs.length?'':' disabled')+'>Send my picks</button><button class="gfb" data-act="clear"'+(favs.length?'':' disabled')+'>Clear</button></div>';
  $('.pk-x',tray).onclick=function(){tray.classList.remove('open')};
  $$('[data-act]',tray).forEach(function(b){b.onclick=function(){
    if(b.dataset.act==='clear'){favs.length=0;store('gf-favs',favs);sync();renderTray()}
    else location.href='mailto:'+EMAIL+'?subject='+encodeURIComponent('My favorites from Gunframe')+'&body='+encodeURIComponent('Hi Kevin! These are my favorites:\n\n'+picksText()+'\n\nThanks!');
  }});
}
