  svg+='</g><path class="land coast" d="'+GEO.coast+'"/>';
  svg+='<rect class="hibox" x="8" y="'+(H-124)+'" width="118" height="100" rx="3"/><path class="land" style="stroke:none" d="'+GEO.hi+'"/><path class="land coast" d="'+GEO.hic+'"/><text class="inset" x="16" y="'+(H-30)+'">HAWAIʻI</text>';
  svg+=lbl('inset',-125.7,31.5,'PACIFIC',0,0,'start')+lbl('inset',-125.7,30.5,'OCEAN',0,0,'start')+lbl('inset',-71.5,35.5,'ATLANTIC',0,0,'start')+lbl('inset',-71.5,34.5,'OCEAN',0,0,'start')+lbl('inset',-91,27.3,'GULF OF MEXICO',0,0,'middle')+lbl('inset',-100,47,'UNITED STATES',0,0,'middle')+lbl('inset',-100,52,'CANADA',0,-2,'middle')+lbl('inset',-104,26.5,'MEXICO',0,0,'middle');
  CITIES.forEach(function(c){var q=pr(c[1],c[2]);svg+='<circle class="city" cx="'+q[0].toFixed(1)+'" cy="'+q[1].toFixed(1)+'" r="2.2"/>'+lbl('citylbl',c[1],c[2],c[0],c[3],c[4],c[5])});
  svg+='<g class="compass" transform="translate('+(W-48)+' 46)"><circle class="cmp-r" r="22"/><path class="cmp-n" d="M0 -22 L5 0 L0 -4 L-5 0Z"/><path class="cmp-s" d="M0 22 L5 0 L0 4 L-5 0Z"/><text class="inset" y="-27" text-anchor="middle">N</text></g>';
  var route=null,home=null;
  if(route&&home){var a=pr(home[1],home[2]),z=pr(route[1],route[2]);svg+='<path class="route" d="M'+a[0]+' '+a[1]+' Q'+((a[0]+z[0])/2)+' '+(Math.min(a[1],z[1])-70)+' '+z[0]+' '+z[1]+'"/>'}
  /* Baja California (the US outlines above stop at the border), so Cabo has land under its pin */
