  var bd='M'+BAJA.map(function(c){var b=pr(c[0],c[1]);return b[0].toFixed(1)+' '+b[1].toFixed(1)}).join('L')+'Z';
  svg+='<path class="land" style="stroke:none" d="'+bd+'"/><path class="land coast" d="'+bd+'"/>'+lbl('inset',-114.2,26.2,'BAJA',0,0,'middle');
